SELECT cn.id, cn.course_id, cn.writer_id, cn.title, cn.content, cn.is_fixed, cn.read_count, cn.created_at, cn.updated_at, cn.deleted_at, c.name AS courseName, u.fullname AS writerName, CASE WHEN f.table_id IS NOT NULL THEN TRUE ELSE FALSE END AS isAttached FROM course_notice cn JOIN course c ON cn.course_id = c.id JOIN `user` u ON cn.writer_id = u.id LEFT JOIN (SELECT DISTINCT table_id FROM file WHERE table_name = 'course_notice' AND deleted_at IS NULL) f ON cn.id = f.table_id
cn.deleted_at IS NULL AND cn.is_fixed = false AND
OR cn.title LIKE CONCAT('%', #{keyword}, '%')
OR cn.content LIKE CONCAT('%', #{keyword}, '%')
OR u.fullname LIKE CONCAT('%', #{keyword}, '%')
AND (CASE WHEN f.table_id IS NOT NULL THEN TRUE ELSE FALSE END) = #{hasAttachment}
AND cn.course_id = #{courseId}
AND c.name = #{courseName}
AND c.is_in_progress = #{isInProgress}
ORDER BY cn.is_fixed DESC,
cn.read_count cn.title cn.created_at ASC DESC, cn.id DESC LIMIT #{skip}, #{pagingSize}

