SELECT cn.id, cn.title, cn.content, cn.is_fixed, cn.created_at, cn.read_count, cn.deleted_at, cn.content, c.name AS courseName, u.fullname AS writerName, CASE WHEN f.table_id IS NOT NULL THEN TRUE ELSE FALSE END AS isAttached FROM course_notice cn JOIN course c ON cn.course_id = c.id JOIN `user` u ON cn.writer_id = u.id LEFT JOIN (SELECT DISTINCT table_id FROM file WHERE table_name = 'course_notice' AND deleted_at IS NULL) f ON cn.id = f.table_id
cn.is_fixed = true AND cn.deleted_at IS NULL
AND cn.course_id = #{courseId}
